-- APPNEST Worker compatibility schema. Legacy production tables are preserved.
CREATE TABLE IF NOT EXISTS appnest_categories(id INTEGER PRIMARY KEY AUTOINCREMENT,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,icon TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO appnest_categories(slug,title,icon,sort_order) SELECT slug,name_ru,icon,sort_order FROM categories;
INSERT OR IGNORE INTO appnest_categories(slug,title,icon,sort_order) VALUES('productivity','Продуктивность','✦',1),('games','Игры','◈',2),('tools','Инструменты','⌘',3),('other','Другое','◇',4);
CREATE TABLE IF NOT EXISTS appnest_apps(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL,developer TEXT NOT NULL DEFAULT '',category TEXT NOT NULL,version TEXT NOT NULL DEFAULT '',version_code INTEGER NOT NULL DEFAULT 0,min_android TEXT NOT NULL DEFAULT '',size_bytes INTEGER NOT NULL DEFAULT 0,apk_key TEXT NOT NULL,apk_sha256 TEXT NOT NULL,icon_key TEXT,banner_key TEXT,screenshots_json TEXT NOT NULL DEFAULT '[]',downloads INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft',created_by TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS idx_appnest_apps_status ON appnest_apps(status,created_at DESC);
CREATE TABLE IF NOT EXISTS appnest_app_versions(id INTEGER PRIMARY KEY AUTOINCREMENT,app_id INTEGER NOT NULL REFERENCES appnest_apps(id) ON DELETE CASCADE,version TEXT NOT NULL,version_code INTEGER NOT NULL DEFAULT 0,min_android TEXT NOT NULL DEFAULT '',size_bytes INTEGER NOT NULL,apk_key TEXT NOT NULL,sha256 TEXT NOT NULL,release_notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS appnest_favorites(user_id TEXT NOT NULL REFERENCES users(telegram_id) ON DELETE CASCADE,app_id INTEGER NOT NULL REFERENCES appnest_apps(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT(datetime('now')),PRIMARY KEY(user_id,app_id));
CREATE TABLE IF NOT EXISTS appnest_downloads(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL REFERENCES users(telegram_id) ON DELETE CASCADE,app_id INTEGER NOT NULL REFERENCES appnest_apps(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS appnest_feedback(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL REFERENCES users(telegram_id) ON DELETE CASCADE,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS appnest_notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,message TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT(datetime('now')));
INSERT INTO appnest_notifications(title,message,active,created_at) SELECT title,body,is_active,created_at FROM notifications;
CREATE TABLE IF NOT EXISTS appnest_required_channels(id INTEGER PRIMARY KEY AUTOINCREMENT,chat_id TEXT NOT NULL UNIQUE,title TEXT NOT NULL,invite_url TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1);
INSERT OR IGNORE INTO appnest_required_channels(chat_id,title,invite_url,enabled) SELECT chat_id,title,invite_url,is_active FROM subscription_channels;
CREATE TABLE IF NOT EXISTS appnest_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO appnest_settings(key,value) VALUES('subscription_mode','all');
CREATE TABLE IF NOT EXISTS appnest_ad_campaigns(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,kind TEXT NOT NULL,creative_url TEXT NOT NULL DEFAULT '',target_url TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,priority INTEGER NOT NULL DEFAULT 0,impressions INTEGER NOT NULL DEFAULT 0,clicks INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT(datetime('now')));
INSERT INTO appnest_ad_campaigns(title,kind,target_url,starts_at,ends_at,active) SELECT title,CASE campaign_type WHEN 'channel_subscription' THEN 'channel' ELSE campaign_type END,target_url,COALESCE(starts_at,datetime('now')),COALESCE(ends_at,datetime('now','+3650 days')),is_active FROM ad_campaigns WHERE campaign_type IN('banner','channel_subscription','task');
CREATE TABLE IF NOT EXISTS appnest_admin_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL DEFAULT '',details TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS appnest_rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS appnest_upload_sessions(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(telegram_id),app_id INTEGER REFERENCES appnest_apps(id),object_key TEXT NOT NULL UNIQUE,r2_upload_id TEXT NOT NULL,metadata_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',expected_size INTEGER NOT NULL,client_sha256 TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT(datetime('now')),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS appnest_upload_parts(upload_id TEXT NOT NULL REFERENCES appnest_upload_sessions(id) ON DELETE CASCADE,part_number INTEGER NOT NULL,etag TEXT NOT NULL,size_bytes INTEGER NOT NULL,PRIMARY KEY(upload_id,part_number));
CREATE TABLE IF NOT EXISTS appnest_ad_frequency(user_id TEXT NOT NULL REFERENCES users(telegram_id) ON DELETE CASCADE,ad_id INTEGER NOT NULL REFERENCES appnest_ad_campaigns(id) ON DELETE CASCADE,day TEXT NOT NULL,impressions INTEGER NOT NULL DEFAULT 0,clicks INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,ad_id,day));
CREATE TABLE IF NOT EXISTS appnest_download_tokens(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(telegram_id) ON DELETE CASCADE,app_id INTEGER NOT NULL REFERENCES appnest_apps(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL,used_at TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')));
